\begin{lemma}[first variation of L-length]
  \label{lem:cz-first-variation-of-l-length}
  \source{cao-zhu}
  \dcref{Lemma 3.2.1}
  \group{Cao--Zhu Comparison Theorems for Perelman's Reduced Volume}
$$
\delta_Y(\mathcal{L})=2\sqrt{\tau}\langle X,Y\rangle|_{\tau_1}^{\tau_2}
+\int_{\tau_1}^{\tau_2}\sqrt{\tau}\left\langle Y,\nabla
R-2\nabla_X X-4\Ric(\cdot,X)-\frac{1}{\tau}X\right\rangle d\tau
$$
where $\langle\cdot,\cdot\rangle$ denotes the inner product with respect to
the metric $g_{ij}(\tau)$.
\end{lemma}

\begin{proof}
  \sketch Differentiate the $\mathcal L$-integrand along the variation and integrate the kinetic term by parts.
\end{proof}

